-- Fills unit_equipment.drones and .mash_theaters (V3_12) for the units V3_8 loaded (importers skill, bug
-- 24): how many drones each drone carrier control system runs and how many operating theaters each MASH
-- has, from their "SIZE" in the unit files. 12 vehicles at the pinned commit; the other units listed in
-- bug 24 are support vehicles, which aren't imported, or have no MUL id.
--
-- Generated from a database V3_8 to V3_12 loaded and the fixed importer then re-imported (mm-data at
-- d195e171b3c87801c8dbc5ffcb5f763e5da57483): nothing else changed. Units are found by MegaMek uuid, and a
-- count is only filled where it's still empty, so this also runs on a database that was re-imported since.
-- Data migrations after V3_8 update what's stored; see the importers skill.

UPDATE unit_equipment SET drones = 6 WHERE id = ANY (ARRAY(SELECT ue.id FROM unit u JOIN unit_mech_equipment ume ON ume.unit_id = u.id JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id JOIN equipment e ON e.id = ue.equipment_id WHERE u.megamek_uuid = '019f583e-e5b0-7011-8788-76ab4bbd1af9' AND e.name = 'drone(remote)carriercontrolsystem' AND e.tech = 'INNER_SPHERE' AND ue.location IS NOT DISTINCT FROM 'BODY' AND ue.drones IS NULL ORDER BY ue.id LIMIT 1)); -- Ajax Assault Tank D
